368. // TestModifyPlanBlocksDefaultContributedHostAdoption covers items 1+2 (iter-32 review):
369. // when unverifiable state (no resolved_spec, matching pre-merge spec_hash) is planned for
370. // update and the provider default_target now contributes an immutable field (here: the
371. // host), ModifyPlan must BLOCK with an executable migration error instead of laundering the
372. // merged identity into the plan — otherwise Update would deploy to the newly-defaulted host
373. // and orphan the original deployment.
374. func TestModifyPlanBlocksDefaultContributedHostAdoption(t *testing.T) {
375. 	t.Setenv("LABDEPLOY_PASSWORD", "pw")
376. 	dir := t.TempDir()
377. 	specPath := filepath.Join(dir, "spec.yaml")
378. 	// Raw spec_file omits target.hosts; the provider default supplies it.
379. 	if err := os.WriteFile(specPath, []byte(wsSpecYAMLNoHost("1.0.0")), 0o600); err != nil {
380. 		t.Fatalf("write spec: %v", err)
381. 	}
382. 	// Provider default_target now points at lab-99 (a DIFFERENT host than was deployed).
383. 	r := &DeploymentResource{pd: &providerData{DefaultTarget: &spec.Target{Hosts: []string{"lab-99"}}}}
384. 	_, hash, contributed, err := r.resolveSpecDetail(context.Background(), &deploymentModel{SpecFile: types.StringValue(specPath)})
385. 	if err != nil {
386. 		t.Fatalf("resolve for baseline hash: %v", err)
387. 	}
388. 	if !contributed {
389. 		t.Fatal("test precondition: provider default_target must contribute the host")
390. 	}
391. 	// Unverifiable state: empty resolved_spec (upgrader declined) but pre-merge hash matches.
392. 	state := &deploymentModel{SpecFile: types.StringValue(specPath), Spec: types.StringNull(),
393. 		ResolvedSpec: types.StringNull(), SpecHash: types.StringValue(hash),
394. 		Hosts: types.ListNull(types.StringType), Variables: types.MapNull(types.StringType)}
395. 	plan := &deploymentModel{SpecFile: types.StringValue(specPath), Spec: types.StringNull(),
396. 		ResolvedSpec: types.StringNull(), SpecHash: types.StringNull(),
397. 		Hosts: types.ListNull(types.StringType), Variables: types.MapNull(types.StringType)}
398. 	resp := runModifyPlan(t, r, plan, state)
399. 	if !resp.Diagnostics.HasError() {
400. 		t.Fatal("ModifyPlan must block adoption of a default-contributed identity on unverifiable state")
401. 	}
402. 	detail := resp.Diagnostics.Errors()[0].Detail()
403. 	if !strings.Contains(detail, "terraform state rm") || !strings.Contains(detail, "terraform apply") {
404. 		t.Fatalf("block must carry the executable state-rm + apply recovery, got %q", detail)
405. 	}
406. }
407. 
408. // TestModifyPlanRecoveryCreateProceeds covers items 1+2 (iter-33 review): the documented
409. // recovery for unverifiable default-dependent state is `terraform state rm` + `terraform
410. // apply`. After state rm there is NO prior state, so the apply flows through Create. This
411. // test proves that create-path planning is NOT blocked (unlike the update path) and that it
412. // carries a resolved_spec snapshot for Create to persist — i.e. the recovery can actually
413. // proceed through planning rather than being rejected by the replacement/Delete guard.
414. func TestModifyPlanRecoveryCreateProceeds(t *testing.T) {
415. 	t.Setenv("LABDEPLOY_PASSWORD", "pw")
416. 	dir := t.TempDir()
417. 	specPath := filepath.Join(dir, "spec.yaml")
418. 	if err := os.WriteFile(specPath, []byte(wsSpecYAMLNoHost("1.0.0")), 0o600); err != nil {
419. 		t.Fatalf("write spec: %v", err)
420. 	}
421. 	// Same default-contributes-host setup that BLOCKS on update...
422. 	r := &DeploymentResource{pd: &providerData{DefaultTarget: &spec.Target{Hosts: []string{"lab-99"}}}}
423. 	plan := &deploymentModel{SpecFile: types.StringValue(specPath), Spec: types.StringNull(),
424. 		ResolvedSpec: types.StringNull(), SpecHash: types.StringNull(),
425. 		Hosts: types.ListNull(types.StringType), Variables: types.MapNull(types.StringType)}
426. 	// ...but with NO prior state (post `terraform state rm`), planning is the create path.
427. 	resp := runModifyPlan(t, r, plan, nil)
428. 	if resp.Diagnostics.HasError() {
429. 		t.Fatalf("recovery create-path planning must NOT be blocked, got %v", resp.Diagnostics.Errors())
430. 	}
431. 	// The plan must carry a resolved_spec so Create persists a VERIFIED snapshot on apply,
432. 	// reaching verified state without a replacement or the guarded Delete.
433. 	var planned deploymentModel
434. 	if d := resp.Plan.Get(context.Background(), &planned); d.HasError() {
435. 		t.Fatalf("read planned model: %v", d)
436. 	}
437. 	if planned.ResolvedSpec.IsNull() || planned.ResolvedSpec.ValueString() == "" {
438. 		t.Fatal("recovery create plan must carry a resolved_spec for Create to persist a verified snapshot")
439. 	}
440. }
