		s.modifiedYAML = e2eWSSpecYAMLHost("1.0.0", "lab-02")
	case "target.os":
		s.baselineYAML = e2eConsoleSpecYAML("windows", "lab-01")
		s.modifiedYAML = e2eConsoleSpecYAML("linux", "lab-01")
