		SpecFile:     types.StringNull(),
		Variables:    types.MapNull(types.StringType),
		ResolvedSpec: types.StringNull(),
		SpecHash:     types.StringNull(),
		Hosts:        types.ListNull(types.StringType),
		Timeouts:     e2eNullTimeouts(),
	}
