	for i, h := range hs {
		lowered[i] = strings.ToLower(h)
	}
	sort.Strings(lowered)
	sum := sha1.Sum([]byte(strings.Join(lowered, ",") + "/" + name))
	s.idExpected = hex.EncodeToString(sum[:])[:12] + ":" + name
