371. func (s *crudState) givenSpecNameHosts(name, hosts string) error {
372. 	hs := splitHosts(hosts)
373. 	d1 := &spec.Deployment{Metadata: spec.Metadata{Name: name}, Target: spec.Target{Hosts: hs}}
374. 
375. 	rev := make([]string, len(hs))
376. 	for i := range hs {
377. 		rev[i] = hs[len(hs)-1-i]
378. 	}
379. 	d2 := &spec.Deployment{Metadata: spec.Metadata{Name: name}, Target: spec.Target{Hosts: rev}}
380. 
381. 	s.idOriginal = provider.DeploymentIDForE2E(d1)
382. 	s.idReordered = provider.DeploymentIDForE2E(d2)
383. 
384. 	lowered := make([]string, len(hs))
385. 	for i, h := range hs {
386. 		lowered[i] = strings.ToLower(h)
387. 	}
388. 	sort.Strings(lowered)
389. 	sum := sha1.Sum([]byte(strings.Join(lowered, ",") + "/" + name))
390. 	s.idExpected = hex.EncodeToString(sum[:])[:12] + ":" + name
391. 	return nil
392. }
