 func (s *crudState) whenPlanComputed() error {
 	resp, err := runPlan(s.baselineYAML, s.modifiedYAML)
 	if err != nil {
 		return err
 	}
 	if resp.Diagnostics.HasError() {
 		return fmt.Errorf("plan computation errored: %v", resp.Diagnostics.Errors())
 	}
 	s.modifyResp = resp
 	return nil
